tokens.data:
(
  100 - (
    min(
      rate(container_cpu_usage_seconds_total{cluster=~"prod-region-1", namespace=~"loki-prod", container="partition-ingester", pod=~"partition-ingester-a.*"}[1m])
    ) / on(pod)
    max(
      rate(container_cpu_usage_seconds_total{cluster=~"prod-region-1", namespace=~"loki-prod", container="partition-ingester", pod=~"partition-ingester-a.*"}[1m])
    )[15m:]
  )
  and on()
  (
    up{job=~"loki-prod/rollout-operator"} > 0
  )
) * 100

sum(
      floor(
        max by (cluster, node) (
          kube_node_status_capacity{resource="cpu", cluster=~"(${cluster:pipe})"}
        )
        - on (cluster, node) group_left(pod) (
          sum by (cluster, node) (
            cluster:namespace:pod_cpu:active:kube_pod_container_resource_requests{cluster=~"(${cluster:pipe})"}
          )
        )
      )
      * on (cluster, node) group_left()
      max by (cluster, node) (node_cpu_hourly_cost{cluster=~"(${cluster:pipe})"})
    ) * 24 * 30

(
  100 - (
    min(
      rate(container_cpu_usage_seconds_total{cluster=~"prod-region-1", namespace=~"loki-prod", container="partition-ingester", pod=~"partition-ingester-a.*"}[1m])
    ) / on(pod)
    max(
      rate(container_cpu_usage_seconds_total{cluster=~"prod-region-1", namespace=~"loki-prod", container="partition-ingester", pod=~"partition-ingester-a.*"}[1m])
    )[15m:]
  )
  and on()
  (
    up{job=~"loki-prod/rollout-operator"} > 0
  )
) * 100
